import { TOKEN_LABEL, type TokenItem } from '~/entities/pin/api/dtos/types';
import { TokenItemType, TokenDetailType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';

export const findTokenItem = (
  tokenList: TokenItem[] | null | undefined,
  key: keyof TokenItem,
  value: string | TokenItemType,
): TokenItem => {
  if (!tokenList) return {} as TokenItem;
  return tokenList.find((item) => item[key] === value) ?? ({} as TokenItem);
};

export const findTokenItemById = (tokenList: TokenItem[] | null | undefined, id: string): TokenItem => {
  if (!tokenList) return {} as TokenItem;
  return findTokenItem(tokenList, 'id', id);
};

export const findTokenItemByType = (tokenList: TokenItem[] | null | undefined, type: TokenItemType): TokenItem => {
  if (!tokenList) return {} as TokenItem;
  return findTokenItem(tokenList, 'type', type);
};

export const getTokenItemLabel = (tokenItem: TokenItem): string => {
  return TOKEN_LABEL[tokenItem.type];
};

export const getTokenDetailType = (tokenList: TokenItem[] | null | undefined, id: string): TokenDetailType => {
  const tokenItem = findTokenItemById(tokenList, id);
  if (tokenItem?.type === TokenItemType.DC2) {
    return tokenItem.bankCd === appConfig.BANK_CODE ? TokenDetailType.DC2_당행 : TokenDetailType.DC2_타행;
  }
  return TokenDetailType.DC1;
};
